mapper.select:
SELECT
FROM sys_user u LEFT JOIN sys_role r ON u.role_id = r.id LEFT JOIN sys_dept d ON u.dept_id = d.id LEFT JOIN sys_user manager ON u.manager_id = manager.id WHERE u.deleted = 0
AND (u.username LIKE CONCAT('%', #{query.keyword}, '%') OR u.nickname LIKE CONCAT('%', #{query.keyword}, '%') OR u.mobile LIKE CONCAT('%', #{query.keyword}, '%'))
AND u.role_id = #{query.roleId}
AND u.dept_id = #{query.deptId}
AND u.status = #{query.status}
ORDER BY u.created_at DESC
